77	/** Groups a feed page by calendar day, newest day first. */
78	export function groupByDay(
79	  events: readonly ActivityEvent[],
80	): readonly ActivityGroup[] {
81	  const byDay = new Map<string, ActivityEvent[]>();
82	
83	  for (const event of events) {
84	    const day = event.occurredAt.slice(0, 10);
85	    const bucket = byDay.get(day) ?? [];
86	    bucket.push(event);
87	    byDay.set(day, bucket);
88	  }
89	
90	  return [...byDay.entries()]
91	    .sort(([a], [b]) => (a < b ? 1 : -1))
92	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
93	}
94	
95	/**
96	 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
97	 * for the role, and on the `csv_export` flag for the plan.
98	 */
99	export async function exportActivity(
100	  actor: Actor,
101	  input: ExportActivityInput,
102	): Promise<string> {
103	  assertOrgScope(actor, input.orgId);
104	  assertCan(actor, "activity:export", activityResource(input.orgId));
105	
106	  const org = await orgRepo.findOrgById(input.orgId);
107	  const flagEnabled = isEnabled("csv_export", {
108	    orgId: input.orgId,
109	    userId: actor.userId,
110	    plan: org?.plan ?? "free",
111	    role: actor.role,
112	    overrides: org?.settings.enabledFlagOverrides,
113	  });
114	
115	  if (input.format === "csv" && !flagEnabled) {
116	    throw new Error("CSV export is not included in this plan");
117	  }
118	
119	  const page = await activityRepo.listActivity({
120	    orgId: input.orgId,
121	    since: input.since,
122	    until: input.until,
123	    limit: 100,
124	    cursor: null,
125	  });
126	
127	  if (input.format === "json") {
128	    return JSON.stringify(page.items, null, 2);
129	  }
130	
131	  return toCsv(
132	    page.items.map((event) => ({
133	      occurredAt: event.occurredAt,
134	      action: event.action,
135	      actorId: event.actorId,
136	      subjectKind: event.subjectKind,
137	      subjectId: event.subjectId,
138	      summary: event.summary,
139	    })),
140	    [...EXPORT_COLUMNS],
141	  );
142	}
