144	/**
145	 * Attaches one handler per audited event type. Called once from
146	 * `event-registry`; the returned function detaches all of them, which is what
147	 * the test suite uses to keep the bus clean between cases.
148	 */
149	export function registerActivityListeners(): Unsubscribe {
150	  const offs: Unsubscribe[] = [
