1	import type {
2	  IsoTimestamp,
3	  MemberId,
4	  OrgId,
5	  SoftDeletable,
6	  TenantScoped,
7	  Timestamps,
8	  UserId,
9	  InvitationId,
10	} from "./common";
11	
12	/**
13	 * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`
14	 * below is the single source of truth for "at least this role" comparisons —
15	 * never compare role strings directly.
16	 */
17	export type Role = "owner" | "admin" | "member" | "viewer";
18	
19	export const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];
20	
21	export const ROLE_RANK: Readonly<Record<Role, number>> = {
22	  owner: 4,
23	  admin: 3,
24	  member: 2,
25	  viewer: 1,
26	};
27	
28	export type MemberStatus = "active" | "invited" | "suspended";
29	
30	export interface User extends Timestamps {
31	  readonly id: UserId;
32	  readonly email: string;
33	  readonly name: string;
34	  readonly avatarUrl: string | null;
35	  readonly timezone: string;
36	  readonly emailVerifiedAt: IsoTimestamp | null;
37	}
38	
39	export interface Member extends Timestamps, TenantScoped, SoftDeletable {
40	  readonly id: MemberId;
41	  readonly userId: UserId;
42	  readonly role: Role;
43	  readonly status: MemberStatus;
44	  readonly invitedBy: UserId | null;
45	  readonly joinedAt: IsoTimestamp | null;
46	  readonly lastSeenAt: IsoTimestamp | null;
47	}
48	
49	/** A member joined with the user record it points at, for list UIs. */
50	export interface MemberWithUser extends Member {
51	  readonly user: User;
52	}
53	
54	export interface Invitation extends Timestamps, TenantScoped {
55	  readonly id: InvitationId;
56	  readonly email: string;
57	  readonly role: Role;
58	  readonly invitedBy: UserId;
59	  readonly token: string;
60	  readonly expiresAt: IsoTimestamp;
61	  readonly acceptedAt: IsoTimestamp | null;
62	  readonly revokedAt: IsoTimestamp | null;
63	}
64	
65	/**
66	 * The authenticated principal for one request, always resolved for exactly one
67	 * organization. Everything that authorizes a mutation takes an `Actor` — see
68	 * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in
69	 * `src/lib/tenant.ts`.
70	 */
71	export interface Actor {
72	  readonly userId: UserId;
73	  readonly orgId: OrgId;
74	  readonly role: Role;
75	  /** Staff impersonation / internal tooling escape hatch. Defaults to false. */
76	  readonly isPlatformStaff?: boolean;
77	}
78	
79	export interface SessionPrincipal {
80	  readonly userId: UserId;
81	  readonly email: string;
82	  readonly activeOrgId: OrgId | null;
83	  readonly expiresAt: IsoTimestamp;
